<div class="stack"><div><h1><?php echo $item ? 'Modifica negozio' : 'Nuovo negozio'; ?></h1><p class="muted">Configura nome, URL e visibilità del partner.</p></div><form class="panel form-grid" action="<?php echo e(url('/admin/stores/save')); ?>" method="post"><?php echo csrf_field(); ?><?php if ($item): ?><input type="hidden" name="id" value="<?php echo e((string) $item['id']); ?>"><?php endif; ?><div class="form-group"><label>Nome</label><input class="form-control" name="name" value="<?php echo e($item['name'] ?? ''); ?>" required></div><div class="form-group"><label>Sito web</label><input class="form-control" name="website" value="<?php echo e($item['website'] ?? 'https://example.com'); ?>"></div><div class="form-group form-group-full"><label>Descrizione</label><textarea class="form-textarea" rows="4" name="description"><?php echo e($item['description'] ?? ''); ?></textarea></div><div class="form-group"><label>Numero offerte</label><input class="form-control" name="offers_count" type="number" value="<?php echo e((string) ($item['offers_count'] ?? 0)); ?>"></div><div class="form-group checkbox"><input type="checkbox" name="featured" value="1" <?php echo ! empty($item['featured']) ? 'checked' : ''; ?>><label>In evidenza</label></div><div class="form-group-full"><button class="btn" type="submit">Salva negozio</button></div></form></div>
